const errData = $input.first().json;
const workflowName = errData.workflow?.name || 'Unknown Workflow';
const errorMsg = errData.execution?.error?.message || 'Unknown error occurred';
const executionId = errData.execution?.id || 'n/a';

console.error(`[LendLoop Automation Error] Workflow: ${workflowName} (Execution: ${executionId}) failed: ${errorMsg}`);

return [{
  json: {
    alert: true,
    workflow: workflowName,
    executionId,
    errorMessage: errorMsg,
    timestamp: new Date().toISOString()
  }
}];
